using System;
using System.IO;
using Aspose.Cells;

class BatchHtmlExporter
{
    // Author: Generated by Aspose.Cells expert for batch HTML conversion with style optimization
    static void Main()
    {
        // Directory containing source XLSX files
        string sourceDir = @"C:\InputXlsx";
        // Directory where HTML files will be saved
        string outputDir = @"C:\OutputHtml";

        // Ensure the output directory exists
        if (!Directory.Exists(outputDir))
        {
            Directory.CreateDirectory(outputDir);
        }

        // Get all .xlsx files in the source directory
        string[] xlsxFiles = Directory.GetFiles(sourceDir, "*.xlsx", SearchOption.TopDirectoryOnly);

        foreach (string xlsxPath in xlsxFiles)
        {
            // Load the workbook
            Workbook workbook = new Workbook(xlsxPath);

            // Configure HTML save options to exclude unused styles (default is true, set explicitly for clarity)
            HtmlSaveOptions htmlOptions = new HtmlSaveOptions
            {
                ExcludeUnusedStyles = true
            };

            // Determine output HTML file name (same base name, .html extension)
            string htmlFileName = Path.GetFileNameWithoutExtension(xlsxPath) + ".html";
            string htmlPath = Path.Combine(outputDir, htmlFileName);

            // Save the workbook as HTML using the configured options
            workbook.Save(htmlPath, htmlOptions);
        }

        Console.WriteLine("Batch HTML export completed.");
    }
}